CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (char_length(display_name)<=60), preferences jsonb NOT NULL DEFAULT '{"wifi_only":true}'::jsonb CHECK (jsonb_typeof(preferences)='object' AND preferences - 'wifi_only' = '{}'::jsonb AND (NOT preferences ? 'wifi_only' OR jsonb_typeof(preferences->'wifi_only')='boolean')));
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hc_account_security (owner_id uuid PRIMARY KEY, revoked_through bigint NOT NULL DEFAULT 0);
GRANT ALL ON public.hc_account_security TO service_role;
ALTER TABLE public.hc_account_security ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hc_revoked_sessions (owner_id uuid NOT NULL, session_id uuid NOT NULL, PRIMARY KEY(owner_id,session_id));
GRANT ALL ON public.hc_revoked_sessions TO service_role;
ALTER TABLE public.hc_revoked_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hc_account_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, event text NOT NULL CHECK(event IN ('profile_created','profile_updated','session_revoked','all_sessions_revoked')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hc_account_audit TO authenticated;
GRANT ALL ON public.hc_account_audit TO service_role;
ALTER TABLE public.hc_account_audit ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.hc_session_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.jwt()->>'session_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hc_revoked_sessions WHERE owner_id=auth.uid() AND session_id=(auth.jwt()->>'session_id')::uuid) AND coalesce((auth.jwt()->>'iat')::bigint,0)>coalesce((SELECT revoked_through FROM public.hc_account_security WHERE owner_id=auth.uid()),0) $$;
REVOKE ALL ON FUNCTION public.hc_session_allowed() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.hc_session_allowed() TO authenticated;
CREATE POLICY profile_read_self ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() AND public.hc_session_allowed());
CREATE POLICY profile_update_self ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() AND public.hc_session_allowed()) WITH CHECK(id=auth.uid() AND public.hc_session_allowed());
CREATE POLICY account_audit_self ON public.hc_account_audit FOR SELECT TO authenticated USING(owner_id=auth.uid() AND public.hc_session_allowed());
CREATE FUNCTION public.hc_create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); INSERT INTO public.hc_account_audit(owner_id,event) VALUES(NEW.id,'profile_created'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.hc_create_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER hc_account_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.hc_create_profile();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE FUNCTION public.hc_profile_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.hc_account_audit(owner_id,event) VALUES(NEW.id,'profile_updated'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.hc_profile_audit() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER hc_profile_updated AFTER UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.hc_profile_audit();
CREATE FUNCTION public.hc_revoke_sessions(p_all boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.hc_session_allowed() THEN RAISE EXCEPTION 'Session expired or revoked'; END IF; IF p_all THEN INSERT INTO public.hc_account_security(owner_id,revoked_through) VALUES(auth.uid(),floor(extract(epoch FROM clock_timestamp()))::bigint) ON CONFLICT(owner_id) DO UPDATE SET revoked_through=greatest(hc_account_security.revoked_through,excluded.revoked_through); ELSE INSERT INTO public.hc_revoked_sessions(owner_id,session_id) VALUES(auth.uid(),(auth.jwt()->>'session_id')::uuid) ON CONFLICT DO NOTHING; END IF; INSERT INTO public.hc_account_audit(owner_id,event) VALUES(auth.uid(),CASE WHEN p_all THEN 'all_sessions_revoked' ELSE 'session_revoked' END); END $$;
REVOKE ALL ON FUNCTION public.hc_revoke_sessions(boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.hc_revoke_sessions(boolean) TO authenticated;